CELLS = ['import torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom d2l import torch as d2l\ntorch.manual_seed(0)\nK, N, T = 5, 600, 50                  # 5 个知识点，600 个学生，每人做 50 题\np_learn = torch.tensor([0.15, 0.10, 0.20, 0.05, 0.12])   # 每做一次学会的概率\np_guess, p_slip = 0.2, 0.1            # 不会也蒙对的概率、会了却做错的概率\nknown = (torch.rand(N, K) < 0.2).float()   # 一开始就会的知识点\nsk = torch.randint(0, K, (N, T))       # 每一步做哪个知识点的题\nrs = torch.zeros(N, T)                 # 对错\ntruth = torch.zeros(N, T)              # 真实的答对概率（模型看不到）\nfor t in range(T):\n    oh = F.one_hot(sk[:, t], K).float()\n    k = (known * oh).sum(1)            # 这一题的知识点会不会\n    p = k * (1 - p_slip) + (1 - k) * p_guess\n    truth[:, t] = p\n    rs[:, t] = (torch.rand(N) < p).float()\n    learn = (torch.rand(N) < (oh * p_learn).sum(1)).float()\n    known = known + oh * (1 - known) * learn.unsqueeze(1)\nsk.shape, rs.shape, sk.dtype, rs.dtype', "print('第 1 个学生前 10 题的知识点：', sk[0, :10].tolist())\nprint('第 1 个学生前 10 题的对错：  ', rs[0, :10].long().tolist())", 'perm = torch.randperm(N)\nte, va, tr = perm[:120], perm[120:168], perm[168:]\nlen(tr), len(va), len(te)', 'class DKT(nn.Module):\n    def __init__(self, K, d=32):\n        super().__init__()\n        self.K = K\n        self.emb = nn.Embedding(2 * K, d); self.lstm = nn.LSTM(d, d, batch_first=True)\n        self.drop = nn.Dropout(0.2); self.out = nn.Linear(d, K)\n\n    def encode(self, sk, rs):\n        x = self.emb(sk + self.K * rs.long()); h, _ = self.lstm(x)\n        return {"h": self.drop(h), "B": sk.shape[0]}\n\n    def readout_all(self, H, qpos):\n        return self.out(H["h"].index_select(1, qpos))\n\n    def readout(self, H, q, qpos):\n        return self.readout_all(H, qpos).gather(-1, q)\n\nmodel = DKT(K)\nmodel', "H = model.encode(sk[:2], rs[:2])\nqpos = torch.arange(T - 1)\nprint('LSTM 每一步的隐状态 h：', H['h'].shape)            # (学生, 时间步, d)\nprint('每一步对所有知识点的 logit：', model.readout_all(H, qpos).shape)   # (学生, 时间步-1, K)\nprint('只取下一题那个知识点的 logit：', model.readout(H, sk[:2, 1:].unsqueeze(-1), qpos).shape)", 'def batch_loss(model, sk, rs):\n    H = model.encode(sk, rs)\n    qpos = torch.arange(sk.shape[1] - 1)\n    logit = model.readout(H, sk[:, 1:].unsqueeze(-1), qpos).squeeze(-1)\n    y = rs[:, 1:]\n    return F.binary_cross_entropy_with_logits(logit, y), logit\n\nl, logit = batch_loss(model, sk[:4], rs[:4])\nl, logit.shape', 'def auc(y, p):\n    """AUC：随机挑一道答对的题和一道答错的题，模型给答对那道更高分的概率"""\n    pairs = sorted(zip(p, y))\n    pos = sum(y); neg = len(y) - pos\n    r, i = 0, 0\n    while i < len(pairs):\n        j = i\n        while j < len(pairs) and pairs[j][0] == pairs[i][0]:\n            j += 1\n        r += (i + j + 1) / 2 * sum(1 for q in range(i, j) if pairs[q][1] == 1)\n        i = j\n    return (r - pos * (pos + 1) / 2) / (pos * neg)\n\ndef eval_bce(model, idx):\n    model.eval()\n    with torch.no_grad():\n        l, logit = batch_loss(model, sk[idx], rs[idx])\n    return l.item(), torch.sigmoid(logit)\n\ndef train_kt(model, epochs=15, lr=2e-3, BS=32):\n    opt = torch.optim.Adam(model.parameters(), lr=lr)\n    best, best_ep, best_state = float(\'inf\'), -1, None\n    for ep in range(epochs):\n        model.train(); p = tr[torch.randperm(len(tr))]\n        for i in range(0, len(p), BS):\n            b = p[i:i + BS]\n            loss, _ = batch_loss(model, sk[b], rs[b])\n            opt.zero_grad(); loss.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 5.0); opt.step()\n        vb, _ = eval_bce(model, va)\n        if vb < best:\n            best = vb; best_ep = ep\n            best_state = {k: v.detach().clone() for k, v in model.state_dict().items()}\n        print(f\'epoch {ep + 1:2d}  验证集 BCE {vb:.4f}\' + (\'  ← 目前最好\' if best_ep == ep else \'\'))\n    model.load_state_dict(best_state)\n    model.eval()\n    return best_ep', 'import math\n\ndef causal_attn(Q, Kt, V, qpos, heads, decay=None):\n    B, Tq, M, d = Q.shape\n    T = Kt.shape[1]; dh = d // heads\n    q = Q.reshape(B, Tq, M, heads, dh).permute(0, 3, 1, 2, 4)\n    k = Kt.reshape(B, T, heads, dh).permute(0, 2, 1, 3)\n    v = V.reshape(B, T, heads, dh).permute(0, 2, 1, 3)\n    s = torch.einsum("bhtmd,bhjd->bhtmj", q, k) / math.sqrt(dh)\n    jpos = torch.arange(T, device=Q.device)\n    dist = qpos.view(-1, 1) - jpos.view(1, -1)\n    if decay is not None:\n        s = s - decay.view(1, heads, 1, 1, 1) * dist.clamp(min=0).float().view(1, 1, Tq, 1, T)\n    s = s.masked_fill((dist < 0).view(1, 1, Tq, 1, T), -1e9)\n    a = torch.softmax(s, -1)\n    o = torch.einsum("bhtmj,bhjd->bhtmd", a, v)\n    return o.permute(0, 2, 3, 1, 4).reshape(B, Tq, M, d)\n\nclass SAKT(nn.Module):\n    def __init__(self, K, d=32, heads=2, maxlen=512):\n        super().__init__()\n        self.K = K\n        self.d, self.h = d, heads\n        self.iemb = nn.Embedding(2 * K, d); self.qemb = nn.Embedding(K, d); self.pos = nn.Embedding(maxlen, d)\n        self.Wq, self.Wk, self.Wv, self.Wo = [nn.Linear(d, d) for _ in range(4)]\n        self.ln1 = nn.LayerNorm(d); self.ln2 = nn.LayerNorm(d)\n        self.ffn = nn.Sequential(nn.Linear(d, d), nn.ReLU(), nn.Dropout(0.2), nn.Linear(d, d))\n        self.drop = nn.Dropout(0.2); self.out = nn.Linear(d, 1)\n\n    def encode(self, sk, rs):\n        T = sk.shape[1]\n        x = self.iemb(sk + self.K * rs.long()) + self.pos(torch.arange(T, device=sk.device)).unsqueeze(0)\n        return {"K": self.Wk(x), "V": self.Wv(x), "B": sk.shape[0]}\n\n    def readout(self, H, q, qpos):\n        Qe = self.qemb(q)\n        o = causal_attn(self.Wq(Qe), H["K"], H["V"], qpos, self.h)\n        o = self.ln1(self.drop(self.Wo(o)) + Qe)\n        o = self.ln2(o + self.drop(self.ffn(o)))\n        return self.out(o).squeeze(-1)\n\nsakt = SAKT(K)\nH = sakt.encode(sk[:2], rs[:2])\nsakt.readout(H, sk[:2, 1:].unsqueeze(-1), torch.arange(T - 1)).shape', "res = {}\nfor name, mk in [('DKT', lambda: DKT(K)), ('SAKT', lambda: SAKT(K))]:\n    torch.manual_seed(1)\n    m = mk()\n    train_kt(m, epochs=15)\n    tb, p_te = eval_bce(m, te)\n    res[name] = (round(tb, 4), round(auc(rs[te][:, 1:].reshape(-1).tolist(), p_te.reshape(-1).tolist()), 4))\nres"]
